b=s.index('    window.__timelines["scene4"] = tl;')
script='''    const tl = gsap.timeline({ paused: true });

    // a slow push into the opening
    tl.fromTo(
      "#s4-cam",
      { scale: 1.0, y: 0, svgOrigin: "960 680" },
      { scale: 1.09, y: -8, duration: 8.1, ease: "power1.inOut" },
      0,
    );

    // rain
    tl.fromTo("#s4-rain-far", { backgroundPosition: "0px 0px" }, { backgroundPosition: "0px 2000px", duration: 8.1, ease: "none" }, 0);
    tl.fromTo("#s4-rain-mid", { backgroundPosition: "0px 0px" }, { backgroundPosition: "0px 3000px", duration: 8.1, ease: "none" }, 0);
    tl.fromTo("#s4-rain-near", { backgroundPosition: "0px 0px" }, { backgroundPosition: "0px 4000px", duration: 8.1, ease: "none" }, 0);
    tl.fromTo("#s4-rain-warm", { backgroundPosition: "0px 0px" }, { backgroundPosition: "0px 2200px", duration: 4.5, ease: "none" }, 0);

    // the hole in the storm ceiling tears open
    tl.fromTo(
      "#s4-hole-shape",
      { scale: 0.035, svgOrigin: "0 0" },
      { scale: 1.6, duration: 3.4, ease: "power2.inOut" },
      0.8,
    );
    tl.fromTo(
      "#s4-hole-rim",
      { scale: 0.035, opacity: 0, svgOrigin: "0 0" },
      { scale: 1.6, opacity: 0.85, duration: 3.4, ease: "power2.inOut" },
      0.8,
    );
    tl.to("#s4-hole-rim", { opacity: 0.38, duration: 2.6, ease: "sine.inOut" }, 4.3);
